use axum::http::{header, StatusCode};
use axum::response::{IntoResponse, Response};
use axum::Json;
use serde_json::json;

#[derive(Debug, thiserror::Error)]
pub enum ProxyError {
    #[error("Unauthorized: {0}")]
    Unauthorized(String),

    #[error("Forbidden: {0}")]
    Forbidden(String),

    #[error("Not found: {0}")]
    NotFound(String),

    #[error("Upstream error: {0}")]
    Upstream(#[from] reqwest::Error),

    #[error("Cache error: {0}")]
    Cache(String),

    #[error("Internal error: {0}")]
    Internal(String),
}

impl IntoResponse for ProxyError {
    fn into_response(self) -> Response {
        let (status, error_message) = match &self {
            ProxyError::Unauthorized(msg) => (StatusCode::UNAUTHORIZED, msg.clone()),
            ProxyError::Forbidden(msg) => (StatusCode::FORBIDDEN, msg.clone()),
            ProxyError::NotFound(msg) => (StatusCode::NOT_FOUND, msg.clone()),
            ProxyError::Upstream(e) => (
                StatusCode::BAD_GATEWAY,
                format!("Upstream registry error: {}", e),
            ),
            ProxyError::Cache(msg) => (StatusCode::INTERNAL_SERVER_ERROR, msg.clone()),
            ProxyError::Internal(msg) => (StatusCode::INTERNAL_SERVER_ERROR, msg.clone()),
        };

        let body = Json(json!({
            "errors": [{
                "code": "PROXY_ERROR",
                "message": error_message,
            }]
        }));

        let mut response = (status, body).into_response();

        // Add WWW-Authenticate header for 401 responses per Docker Registry V2 API spec
        if matches!(self, ProxyError::Unauthorized(_)) {
            response.headers_mut().insert(
                header::WWW_AUTHENTICATE,
                header::HeaderValue::from_static(r#"Basic realm="Docker Registry Proxy""#),
            );
        }

        response
    }
}

pub type Result<T> = std::result::Result<T, ProxyError>;

mod auth;
mod cache;
mod config;
mod error;
mod registry;
mod upstream;

use crate::auth::{auth_middleware, AuthState};
use crate::cache::BlobCache;
use crate::config::Config;
use crate::registry::RegistryState;
use crate::upstream::UpstreamClient;
use axum::{
    middleware,
    routing::{get, put},
    Router,
};
use std::sync::Arc;
use tower_http::trace::TraceLayer;
use tracing::info;
use tracing_subscriber::{layer::SubscriberExt, util::SubscriberInitExt};

#[tokio::main]
async fn main() -> anyhow::Result<()> {
    tracing_subscriber::registry()
        .with(
            tracing_subscriber::EnvFilter::try_from_default_env()
                .unwrap_or_else(|_| "docker_registry_proxy=debug,tower_http=debug".into()),
        )
        .with(tracing_subscriber::fmt::layer())
        .init();

    let config_path = std::env::var("CONFIG_PATH").unwrap_or_else(|_| "config.toml".to_string());
    let config = Config::from_file(&config_path)?;

    info!("Starting Docker Registry Proxy");
    info!("Cache directory: {:?}", config.cache.directory);
    info!(
        "Cache limits: max_size={} bytes, max_age={} seconds",
        config.cache.max_size_bytes, config.cache.max_age_seconds
    );
    info!("Configured {} upstream registries", config.registries.len());
    info!(
        "Configured {} repository mappings",
        config.repositories.len()
    );

    let cache = Arc::new(BlobCache::new(config.cache.clone()).await?);
    BlobCache::start_cleanup_task(cache.clone()).await;

    let upstream = UpstreamClient::new();

    let registry_state = Arc::new(RegistryState {
        config: config.clone(),
        upstream,
        cache,
    });

    let auth_state = Arc::new(AuthState {
        jwt_secret: [REDACTED],
    });

    let app = Router::new()
        .route("/v2/", get(registry::handle_version_check))
        .route(
            "/v2/:repository/manifests/:reference",
            get(registry::handle_get_manifest)
                .put(registry::handle_unsupported_write)
                .delete(registry::handle_unsupported_write),
        )
        .route(
            "/v2/:repository/blobs/:digest",
            get(registry::handle_get_blob)
                .head(registry::handle_head_blob)
                .delete(registry::handle_unsupported_write),
        )
        .route(
            "/v2/:repository/blobs/uploads/",
            put(registry::handle_unsupported_write),
        )
        .route("/v2/:repository/tags/list", get(registry::handle_get_tags))
        .layer(middleware::from_fn_with_state(
            auth_state.clone(),
            auth_middleware,
        ))
        .layer(TraceLayer::new_for_http())
        .with_state(registry_state);

    let bind_addr = format!("{}:{}", config.server.bind_address, config.server.port);
    info!("Listening on {}", bind_addr);

    let listener = tokio::net::TcpListener::bind(&bind_addr).await?;
    axum::serve(listener, app).await?;

    Ok(())
}

use jsonwebtoken::{encode, EncodingKey, Header};
use serde::{Deserialize, Serialize};
use std::env;

#[derive(Debug, Serialize, Deserialize)]
struct Claims {
    sub: String,
    exp: Option<usize>,
    access: AccessLevel,
}

#[derive(Debug, Serialize, Deserialize)]
#[serde(tag = "type", rename_all = "lowercase")]
enum AccessLevel {
    All,
    Repositories { repos: Vec<String> },
}

fn main() {
    let args: Vec<String> = env::args().collect();

    if args.len() < 3 {
        eprintln!("Usage: {} <secret> <subject> [repo1,repo2,...]", args[0]);
        eprintln!("Examples:");
        eprintln!("  {} my-secret user123", args[0]);
        eprintln!("  {} my-secret user123 alpine,nginx", args[0]);
        std::process::exit(1);
    }

    let secret = &args[1];
    let subject = &args[2];

    let access = if args.len() > 3 {
        let repos: Vec<String> = args[3].split(',').map(|s| s.to_string()).collect();
        AccessLevel::Repositories { repos }
    } else {
        AccessLevel::All
    };

    let claims = Claims {
        sub: subject.to_string(),
        exp: None,
        access,
    };

    let token = encode(
        &Header::default(),
        &claims,
        &EncodingKey::from_secret(secret.as_bytes()),
    )
    .expect("Failed to encode token");

    println!("{}", token);
}
